/* Where the last install wrote down what it stored. Not a real file — a key
   the cache will hold a response under, which is the only durable note a
   service worker gets to keep. */
const STAMP = "__asset-stamp__";

/*
 * The page: three small files, fetched together whenever the build changes.
 * The length check re-fills a cache left half-written by an install that failed
 * partway through.
 */
async function fill(name, urls) {
  const cache = await caches.open(name);
  /*
   * cache: "reload" on every one of them, and never addAll.
   *
   * addAll fetches through the browser's HTTP cache, and GitHub Pages serves
   * the page with max-age=600 — so an install that ran inside ten minutes of a
   * push could store a page that was already out of date, and then serve it
   * forever. That is exactly what "the banner says there's an update, I tap it,
   * nothing happens" looks like from the outside.
   */
  await Promise.all(urls.map(async (url) => {
    try {
      const res = await fetch(url, { cache: "reload" });
      if (res && res.ok) await cache.put(url, res.clone());
    } catch (e) { /* the launch that needs it falls through to the network */ }
  }));
}

/*
 * The assets: only the ones that actually moved.
 *
 * Each is compared against what the last install wrote down. Same hash and
 * still in the cache, and it is left alone; anything else is fetched. Files no
 * longer in the build are dropped, so a removed card's picture does not sit
 * there forever.
 *
 * A fetch that fails leaves the old copy and the old stamp for that file, so a
 * flaky connection costs an out-of-date picture rather than a missing one.
 */
async function fillAssets() {
  const cache = await caches.open(ASSET_CACHE);
  let had = {};
  try {
    const note = await cache.match(STAMP);
    if (note) had = await note.json();
  } catch (e) { had = {}; }

  const wanted = Object.keys(ASSET_HASHES);
  const stored = Object.assign({}, had);

  for (const url of wanted) {
    const same = had[url] === ASSET_HASHES[url];
    if (same && (await cache.match(url))) continue;
    try {
      const res = await fetch(url, { cache: "reload" });
      if (!res || !res.ok) continue;
      await cache.put(url, res.clone());
      stored[url] = ASSET_HASHES[url];
    } catch (e) { /* keep whatever is already there */ }
  }

  for (const req of await cache.keys()) {
    const here = new URL(req.url);
    const rel = here.pathname.split("/").slice(-2).join("/");
    if (req.url.indexOf(STAMP) !== -1) continue;
    if (ASSET_HASHES[rel] === undefined) {
      await cache.delete(req);
      delete stored[rel];
    }
  }

  await cache.put(STAMP, new Response(JSON.stringify(stored), {
    headers: { "Content-Type": "application/json" },
  }));
}

/*
 * The page first, and nothing waits on the pictures.
 *
 * Installing used to hold activation until all fifty-odd assets had been
 * checked — sixty megabytes of artwork and music. On a phone with course signal
 * that can outlast the app: close it before the sweep finishes and the new
 * worker never takes over, so the phone keeps serving the build it already had
 * and looks like it will not update. The page is 600 KB; it is the only thing
 * an update actually needs.
 *
 * So the assets are swept alongside rather than in front of it, and whatever
 * the sweep does not reach is fetched from the network on demand and picked up
 * by the next install.
 */
self.addEventListener("install", (event) => {
  event.waitUntil(fill(PAGE_CACHE, PAGE_FILES).then(() => self.skipWaiting()));
  event.waitUntil(fillAssets().catch(() => null));
});

self.addEventListener("activate", (event) => {
  const keep = [PAGE_CACHE, ASSET_CACHE];
  event.waitUntil(
    caches.keys()
      .then((keys) => {
        const stale = keys.filter((k) => keep.indexOf(k) === -1);
        /*
         * An older page cache was here, so this is an upgrade rather than a
         * first install — and whatever windows are open are running the build
         * that cache held. They are told, so the reload is offered rather than
         * waited for on the next launch.
         */
        const upgrade = stale.some((k) => k.indexOf("chainreaction-page-") === 0);
        return Promise.all(stale.map((k) => caches.delete(k))).then(() => upgrade);
      })
      .then((upgrade) => self.clients.claim().then(() => {
        if (!upgrade) return null;
        return self.clients.matchAll({ type: "window" })
          .then((cs) => cs.forEach((c) => c.postMessage({ type: "newbuild" })))
          .catch(() => null);
      })),
  );
});

/*
 * The page is fresh-first, with a short fuse. Everything else is cache-first.
 *
 * Both extremes were tried and both were wrong. Network-first with no limit
 * meant every launch sat on a dark screen until the network answered, which on
 * course signal is exactly when it will not. Cache-first meant a new build
 * landed a launch late — and a phone could sit on an old version for days while
 * its owner reasonably concluded the app was broken. That cost far more than
 * the wait it saved.
 *
 * So: ask for the page, and if the answer comes inside NAV_WAIT_MS, that is
 * what gets drawn — a push reaches the table on the very next launch. If it
 * does not, the stored page is drawn instead and the fetch is left running to
 * replace it for next time. Worst case is a brief wait; there is no case where
 * a phone is stuck on an old build while online.
 */
const NAV_WAIT_MS = 1200;

self.addEventListener("fetch", (event) => {
  if (event.request.method !== "GET") return;

  if (event.request.mode === "navigate") {
    event.respondWith((async () => {
      /*
       * cache: "no-store" goes past the browser's HTTP cache as well as ours —
       * Pages serves the page with max-age=600, so without it a launch inside
       * ten minutes of a push can be handed the copy from before it.
       *
       * Stored under the key the cache is read from. Against the request URL
       * instead, the copy the next launch reads was never the copy this one
       * replaced, so a page cached stale stayed stale however often it was
       * reloaded — and every query string kept a copy of its own.
       */
      const fresh = fetch(event.request, { cache: "no-store" }).then((res) => {
        if (res && res.ok) {
          const copy = res.clone();
          caches.open(PAGE_CACHE).then((c) => c.put("index.html", copy)).catch(() => {});
        }
        return res;
      });
      const stored = await caches.match("index.html");
      // Nothing stored yet: the first launch has the network or nothing.
      if (!stored) {
        return fresh.catch(() => caches.match(event.request));
      }
      const answered = await Promise.race([
        fresh.then((res) => (res && res.ok ? res : null)).catch(() => null),
        new Promise((r) => setTimeout(() => r(null), NAV_WAIT_MS)),
      ]);
      // Whichever arrived first; the fetch keeps going either way, so a page
      // that lost the race still replaces the stored one for next time.
      return answered || stored;
    })());
    return;
  }

  // caches.match with no cacheName searches both of ours.
  event.respondWith(
    caches.match(event.request).then((hit) => hit || fetch(event.request)),
  );
});
